from GROUND_TRUTH import chomp

# Hypothesis: d(q) := f(q,r)-q satisfies d(q) <= d(r) for all q >= r+3.
# Test for r up to some bound, scanning q up to horizon (live part; after stale, d<0 so trivially ok).
# For live rows we need to scan the whole periodic tail too.

