    rows = chomp.row(r, qmax=qmax)
    dr = None
    worst = None
    worstq = None
    for q,f,df in rows:
        if q == r:
            dr = df
        if q >= r+3:
            if df > dr + 0.0001:
                return (False, q, df, dr)
            # track worst
    return (True, None, None, dr)

bad = []
for r in range(1, 2001):
